 raw=PACK.read_bytes();p=loads(raw)
 if any(r['itemId']=='prov-ca-u26-postal-capability' for r in p['provenanceRecords']):print('Already repaired');return
 u=next(x for x in p['units'] if x['number']==26);obj='obj-u26-postal-address';s=next(x for x in u['sessions'] if x['id']=='u26-s-gap-postal-address');o=next(x for x in u['objectives'] if x['id']==obj);items=[i for i in p['items'] if i['objectiveId']==obj];template=next(r for r in p['provenanceRecords'] if r['itemId']=='prov-ca-17-72');added=[]
 bibliography='Primary Russian Post https://info.pochta.ru/support/post-rules/write-address retrieved2026-10-11: components and context-dependent addressing. Primary UPU Russian Federation sheet https://www.upu.int/UPU/media/upu/PostalEntitiesFiles/addressingUnit/rusEn.pdf retrieved2026-10-11; printed01/2013, not a new2026 standard; postcode examples and international country-last processing note. Independent English synthesis using retained Russian cues; no new Russian generation, copied book prose or source asset; review pending.'
