 teaches=[x for x in s['steps'] if x['kind']=='TEACH'];assert len(teaches)==2
 for st,title,body in zip(teaches,['Distinguish recipient, premises, locality and numeric code','Apply the supplied format and its conditional limits'],[part1,part2]):st.update(title=title,body=body)
 s['steps']=teaches+[x for x in s['steps'] if x['kind']!='TEACH'];rem=next(x for x in s['steps'] if x['id']=='u26-postal-remediate');rem.update(title='Review all address components and format limits',body=part1+'\n\n'+part2,exampleIds=list(dict.fromkeys(e for st in teaches for e in st.get('exampleIds',[]))))
 next(x for x in s['steps'] if x['id']=='u26-postal-guided')['body']='Identify the requested locality component in the supplied model. A miss restores the full component and formatting explanation.'
 next(x for x in s['steps'] if x['id']=='u26-postal-check')['body']='Identify components and conditional details, then recognize the displayed order in this supplied format. These checks do not verify deliverability or a universal postal order.'
 cap=next(c for c in p['sourceCapabilities'] if c['id']=='cap-obj-u26-postal-address');oldcap=deepcopy(cap);texts=[s['title']]+[v for st in s['steps'] if st['id'] in o['instructionStepIds']+o['practiceStepIds']+o['remediationStepIds'] or st['id']=='u26-postal-check' for v in (st['title'],st['body'])]+[v for i in items for v in [i['prompt'],i['promptLetter'],i['feedback']]+i['options']+i['distractorRationales'] if v];apps=[dict(cue=i['promptLetter'],answer=i['answer'],distractors=[x for x in i['options'] if x!=i['answer']]) for i in items];span=bibliography+'\n'+'\n'.join(dict.fromkeys(texts))+'\n'+json.dumps(apps,ensure_ascii=False);cap.update(sourceId='src-content-audit-research',sourceRevision='content-audit-2026-10-08',sourceRecordId='ca-corrected-capability:'+cap['id'],sourceHash=sha(span),exactSpan=span);seen={}
 def record(text,name):
  if text in seen:return seen[text]
  r=deepcopy(template);r.update(itemId='prov-ca-u26-postal-'+name,unitNumber=26,objectiveId=obj,sourceRecordId=cap['sourceRecordId'],recordType='label',originalSourceText=span,shippedText=text,sourceHash=sha(span),contentHash=sha(text),attribution='Russian Companion independent English postal-format correction,2026-10-11; retained Russian examples; no owned-book prose.');r['synthesis'].update(bibliography=bibliography,objectiveOrClaimBinding=obj+':postal-address',authorshipDeclaration='Independent English contextual application synthesis,2026-10-11; no copied book prose or new Russian generation.',applications=apps);p['provenanceRecords'].append(r);added.append(r['itemId']);seen[text]=r['itemId'];return r['itemId']
 record(s['title'],'capability')
 for n,text in enumerate(dict.fromkeys(texts)):record(text,'coverage-'+str(n))
 for i in items:
  parts=[record(text,i['id']+'-participant-'+str(n)) for n,text in enumerate([i['promptLetter']]+i['options'])];i['assessment'].update(relationParticipantIds=parts,answerSourceIds=[parts[1]],distractorSourceIds=['']+parts[2:])
 pin=ROOT/'app/src/main/java/dev/russiancompanion/v2/curriculum/ContentAuditCapabilityPins.kt';features=sorted(i['assessment']['testedFeature'] for i in items if i['assessment']['independent']);line='        Pin("'+cap['id']+'", "'+cap['sourceRecordId']+'", "'+cap['sourceHash']+'", 26, "'+obj+'", "postal-address", setOf('+', '.join('"'+f+'"' for f in features)+')),\n';pin.write_text(pin.read_text().replace('    val all = listOf(\n','    val all = listOf(\n'+line))
